import java.util.Scanner;

public class Main {
    static int tran(int a, int b) {
        int t;
        int res = 0;
        int pow = 1;
        do {
            t = a / b;
            res += pow * (a - (a / b) * b);
            a = t;
            pow *= 10;
        } while (t >= b);
        res += pow * t;
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int b = scanner.nextInt();
        for (int i = 1; i < b; i++) {
            for (int j = 1; j < b; j++) {
                System.out.print(tran(i * j, b) + " ");
            }
            System.out.println();
        }
        scanner.close();
    }
}

